const threshold = 50; // ubah nilai ini untuk melihat perubahan klasifikasi

const labeledData = [
  { x: 10, y: 0 },
  { x: 20, y: 0 },
  { x: 60, y: 1 },
  { x: 80, y: 1 }
];

function predict(x) {
  return x >= threshold ? 1 : 0;
}

let correct = 0;
for (const d of labeledData) {
  const yHat = predict(d.x);
  if (yHat === d.y) correct++;
}

const newSamples = [30, 45, 55, 90];
const predictions = newSamples.map(x => ({ x, yHat: predict(x) }));

console.log('Threshold:', threshold);
console.log('Accuracy on labeledData:', `${correct}/${labeledData.length}`);
console.log('Predictions for new samples:', predictions);

let clusterCenterA = 25; // ubah nilai ini
let clusterCenterB = 75; // ubah nilai ini

const unlabeledPoints = [5, 12, 18, 27, 33, 62, 70, 78, 90];

function distance(a, b) { return Math.abs(a - b); }

const clusters = { A: [], B: [] };

for (const p of unlabeledPoints) {
  const dA = distance(p, clusterCenterA);
  const dB = distance(p, clusterCenterB);
  if (dA <= dB) clusters.A.push(p);
  else clusters.B.push(p);
}

console.log('Centers => A:', clusterCenterA, 'B:', clusterCenterB);
console.log('Cluster A points:', clusters.A);
console.log('Cluster B points:', clusters.B);

console.log('Insight: Tidak ada label benar/salah, tapi kita menemukan pembagian alami dari data.');

let rewardGood = 1; // ubah
let rewardBad = 0;  // ubah

// Aksi: 0 = aksi buruk, 1 = aksi baik (lingkungan disetel sederhana)
function envStep(action) {
  if (action === 1) return rewardGood;
  return rewardBad;
}

// Q-value sederhana untuk 2 aksi
let Q = [0, 0];
let alpha = 0.3; // learning rate
let epsilon = 0.2; // exploration rate

function chooseAction() {
  // epsilon-greedy
  if (Math.random() < epsilon) return Math.random() < 0.5 ? 0 : 1;
  return Q[1] >= Q[0] ? 1 : 0;
}

for (let episode = 1; episode <= 30; episode++) {
  const action = chooseAction();
  const reward = envStep(action);

  // update Q (bandit setting: target = reward)
  Q[action] = Q[action] + alpha * (reward - Q[action]);

  if (episode % 10 === 0) {
    console.log('Episode', episode, 'Chosen action', action, 'Reward', reward, 'Q', Q);
  }
}

console.log('Final Q-values:', Q);
console.log('Jika Q aksi 1 lebih tinggi, agen akan memilih aksi baik lebih sering.');
